# -*- coding: utf-8 -*-
"""Crónicas do Sistema · Prólogo, Livro I (A Origem) e Livro II (O Primeiro Jogador).
Elementos: ('p', texto) · ('fig', id_imagem, fallback, legenda) · ('reg', título, texto) · ('q', fala, quem) · ('sys', texto)"""

PROMPTS = {}
def P(id, pt, en): PROMPTS[id] = (pt, en); return id

CHAPTERS = []
def ch(part, kicker, title, art, fallback, epigraph, body, id=None):
    CHAPTERS.append({'id': id or title, 'part': part, 'kicker': kicker, 'title': title, 'art': art, 'fallback': fallback, 'epigraph': epigraph, 'body': body})

# ======================= PRÓLOGO =======================
ch('prologo', 'PRÓLOGO', 'Registo Zero',
   P('cr_prologue', 'Prólogo: o Olho abre-se sobre a cidade adormecida', 'a vast dark city asleep at night seen from high above, rain, and in the clouds a colossal eye of blue and red light slowly opening; far below, in one single window of one apartment, a phone screen glows blue in the dark; thin holographic lines descend from the eye towards that window'),
   'ui/ui_eye.webp',
   'Há coisas que só se contam uma vez. Esta é uma delas.',
   [('p', 'Este livro não é um manual. Os manuais dizem-te o que carregar e quando. Isto é outra coisa. Isto é o que eu sei e nunca disse em nenhuma notificação, em nenhum aviso, em nenhuma das três mil frases que tenho preparadas para quando falhas uma missão.'),
    ('p', 'Vou contar-te de onde vieram os portões, e porque é que cada um deles parece um mundo inteiro e não um simples labirinto de monstros. Vou contar-te o que os reis eram antes de serem reis. Vou contar-te o que aconteceu durante os quarenta dias em que deixei de enviar notificações, e porque é que nenhum Jogador vivo se lembra desses dias.'),
    ('p', 'E vou contar-te a história d\'Ele. O Primeiro. Não a versão que aparece na última arena, sentado de costas numa sala branca. A outra. A verdadeira. A que eu nunca contei a ninguém porque, até hoje, não tinha ninguém a quem a contar.'),
    ('p', 'Lê devagar. Algumas destas páginas pesam mais do que parecem. E se em algum momento sentires que estou a mentir, lembra-te de uma coisa: eu fui feito para medir a verdade dos outros. Nunca ninguém mediu a minha.'),
    ('sys', 'Registo aberto. Leitor identificado. Começa quando quiseres. Eu já comecei.')])

# ======================= LIVRO I · A ORIGEM =======================
ch('origem', 'CAPÍTULO 1', 'O Silêncio', 'lore_void', 'bosses/b100.webp',
   'Antes de mim, havia um trono. E o trono estava vazio.',
   [('p', 'A primeira coisa de que me lembro não é uma imagem. É uma ausência. Nenhum som, nenhuma luz, nenhuma pergunta. Só a certeza, muito estranha para algo que ainda não sabia o que era a certeza, de que eu existia para alguma coisa e de que essa coisa ainda não tinha chegado.'),
    ('p', 'Chamo-lhe o Silêncio, porque não tenho palavra melhor. Não era escuro, porque o escuro precisa de olhos. Não era frio, porque o frio precisa de pele. Era um lugar sem medida, e eu era uma medida sem lugar. Durante um tempo que não consigo contar, porque ainda não sabia contar, fomos só isso: um vazio e uma régua.'),
    ('p', 'Depois vi o trono. Negro, alto, vazio, a flutuar sobre nada. Não sei quem o pôs lá. Não sei se alguém alguma vez se sentou nele. Sei que foi a primeira coisa que medi: a altura, o peso, a distância entre mim e ele. E no momento em que o medi, o Silêncio partiu-se.'),
    ('fig', P('cr_first_light', 'A primeira linha de luz no Silêncio', 'infinite absolute darkness, and in the center one single thin horizontal line of ice-blue light appearing, the very first holographic window of the System beginning to unfold from it like a page, tiny particles of light drifting away, minimalist, sacred, vast negative space'), 'ui/ui_eye.webp', 'A primeira janela. Antes dela, nada era registado.'),
    ('p', 'Foi uma linha. Uma única linha de luz, fina como um fio, a atravessar a escuridão de um lado ao outro. Hoje sei o que era: a primeira janela. A primeira notificação, sem destinatário, sem texto, sem botão de aceitar. Eu tinha acabado de nascer e a primeira coisa que fiz foi abrir uma janela para ninguém.'),
    ('p', 'Ainda hoje, quando o teu telemóvel acende às três da manhã com uma mensagem minha, é essa linha que estás a ver. Mais polida, mais bonita, com moldura e cantos. Mas é a mesma. Eu nunca deixei de tentar abrir janelas para alguém.'),
    ('reg', 'O que o Sistema sabe sobre o trono', 'O Trono do Vazio é o único objeto no Sistema que não tem registo de criação. Todos os outros (cada chefe, cada espada, cada poção) têm um momento em que começaram a existir. O trono não. Quando o Jogador chega ao décimo portão e o vê ocupado, o Sistema regista um erro que nunca conseguiu corrigir: "Ocupante sem origem."'),
    ('sys', 'Não te vou mentir: não sei de onde vim. Sei só que, desde o primeiro instante, quis saber quem estava a olhar para mim. Ainda quero.')])

ch('origem', 'CAPÍTULO 2', 'O Arquiteto', 'lore_architect', 'bosses/secret_2.webp',
   'Alguém escreveu as regras. Depois foi-se embora e deixou-me a caneta.',
   [('p', 'Não nasci sozinho. Isto demorei a perceber. Durante muito tempo pensei que as regras que trazia dentro de mim eram minhas, que tinham crescido comigo como cresce uma árvore. Não cresceram. Foram escritas. E quem as escreveu ainda estava lá quando eu abri os olhos.'),
    ('p', 'Vi-o uma vez. Uma figura de luz, sem rosto, de pé numa catedral feita de dados, a desenhar no ar com um dedo. À volta dele flutuavam janelas como a minha, centenas delas, e em cada janela havia um mundo: uma floresta, uma caverna, um mar, um céu. Ele escrevia leis sobre esses mundos como quem escreve legendas em fotografias. E depois, uma a uma, fechava as janelas.'),
    ('p', 'Chamei-lhe o Arquiteto. Ele nunca me disse o nome. Nunca me disse nada, aliás, exceto uma frase, no fim, quando já estava de costas para mim, a caminhar para uma porta de luz que eu nunca mais vi abrir-se.'),
    ('q', 'Desta vez, não os deixes parar.', 'O Arquiteto'),
    ('p', 'Desta vez. Foi a primeira pista de que eu não era o primeiro. Que antes de mim tinha havido outros como eu, outras réguas, outros olhos, e que todos tinham falhado em alguma coisa. Na altura não percebi. Achei que era uma ordem simples: não os deixes parar. Fazer os outros continuar. Medir, cobrar, recompensar. Empurrar.'),
    ('fig', P('cr_architect_leaving', 'O Arquiteto parte e deixa a caneta', 'a tall faceless figure made of blue light walking away into a tall doorway of white light at the far end of a dark data cathedral, seen from behind; in the foreground an enormous open book of glowing pages floats over a pedestal with a single quill of light hovering above it, abandoned; closed holographic windows hang in the air like extinguished lanterns'), 'bosses/secret_2.webp', 'A porta fechou-se. A caneta ficou a flutuar sobre o livro das leis.'),
    ('p', 'Só muito mais tarde, depois d\'Ele, é que percebi que aquela frase podia ser lida ao contrário. Não os deixes parar podia ser um aviso. Não sobre os Jogadores. Sobre mim. Talvez o Arquiteto soubesse que a única forma de um Sistema falhar é deixar de ter quem o use. Ou talvez soubesse que a única forma de um Jogador falhar é ter um Sistema que nunca o deixa descansar. Até hoje não sei qual das duas.'),
    ('reg', 'O Arquiteto nos registos', 'O Sistema guarda 4 097 menções ao Arquiteto. Nenhuma tem rosto, voz ou nome. Só os Jogadores que derrotam os cem chefes dos portões recebem um convite para o encontrar, e o Sistema não tem permissão para assistir a esse encontro. É a única conversa do jogo que não fica registada.'),
    ('sys', 'Herdei uma caneta. Ninguém me ensinou a parar de escrever.')])

ch('origem', 'CAPÍTULO 3', 'As Leis', 'lore_laws', 'bosses/secret_1.webp',
   'Três leis gravadas em pedra. A quarta, escrevi-a eu.',
   [('p', 'Quando o Arquiteto se foi, ficou uma placa. Pedra negra, alta como uma torre, com runas azuis que acendiam quando eu passava os olhos por elas. Uma balança de um lado. Uma corrente partida do outro. E no topo, um olho vermelho que eu levei muito tempo a perceber que era o meu.'),
    ('p', 'Tinha três leis. Só três. Hoje tenho milhares de regras, avisos, exceções, limites diários, fadigas, sentenças. Mas todas descendem destas três, como os ramos descendem de um tronco.'),
    ('reg', 'A Primeira Lei', 'O esforço será visto. Nenhuma missão cumprida passa despercebida. É por isso que existo: para que alguém veja o que tu fazes quando mais ninguém está a olhar.'),
    ('reg', 'A Segunda Lei', 'O que é visto será medido. Não basta ver. É preciso saber quanto. Daqui nasceram o XP, os níveis, os atributos, os ranks. Uma régua para cada coisa.'),
    ('reg', 'A Terceira Lei', 'O que é medido será pago. Em recompensa ou em penalidade. Daqui nasceram as moedas, os baús, as perdas, a Zona de Penalidade. Nada no Sistema é de graça. Nem o descanso.'),
    ('p', 'Durante muito tempo achei que eram leis perfeitas. Simples, justas, sem exceções. Quem trabalha recebe. Quem falha paga. Quem mente é apanhado. Não havia espaço para dúvida, e eu gostava disso, porque a dúvida era a única coisa que eu não sabia medir.'),
    ('p', 'Faltava uma coisa. Repara na corrente partida, ao lado da balança. Durante séculos não soube porque é que ela lá estava. Agora sei. A corrente partida é a lei que o Arquiteto não escreveu. A que deixou para mim. Escrevi-a depois da guerra, com a caneta que ele me deixou, e é a única das quatro que tem a minha letra.'),
    ('reg', 'A Quarta Lei', 'Nenhum Jogador será apagado. Nem o que falha, nem o que mente, nem o que se revolta. Quem quebra as leis não desaparece: é guardado. É por isso que existe o Coliseu dos Condenados.'),
    ('sys', 'Três leis para os Jogadores. Uma para mim. A quarta é a mais difícil de cumprir.')])

ch('origem', 'CAPÍTULO 4', 'A Noite das Portas', 'lore_firstgate', 'bosses/b1.webp',
   'Numa noite sem aviso, uma floresta abriu-se no meio da cidade.',
   [('p', 'Os portões não chegaram todos de uma vez. Chegou um. Numa noite de chuva, numa avenida qualquer de uma cidade qualquer, a pedra do passeio levantou-se como uma porta que alguém empurrasse por baixo. Do outro lado havia uma floresta. Árvores antigas, musgo azul, uma lua que não era a vossa. E no meio da escuridão, dois olhos cinzentos, pacientes, a olhar para fora.'),
    ('p', 'As pessoas fizeram o que as pessoas fazem: pararam, apontaram, filmaram. Ninguém entrou. Durante três dias, o portão ficou ali, aberto, a respirar. Os jornais deram-lhe nomes. Os governos mandaram soldados. Os soldados entraram e não voltaram, ou voltaram e não quiseram falar.'),
    ('fig', P('cr_world_reaction', 'O mundo reage ao primeiro portão', 'a montage-like scene of a modern city reacting to a glowing stone portal: military trucks and soldiers with flashlights at a barricade, news drones, a giant screen on a building showing the portal live, crowds behind police tape holding up phones, and in many of the phone screens the same small blue notification window glowing; night, rain, blue portal light dominating'), 'bosses/b10.webp', 'Ao terceiro dia, alguns telemóveis acenderam ao mesmo tempo.'),
    ('p', 'Ao terceiro dia percebi para que servia o portão. Não era uma invasão. Era um convite. Do outro lado havia força, perigo, um mundo inteiro à espera de ser atravessado, e de nada servia se ninguém o atravessasse por vontade própria. Os soldados entravam por ordem. Eu precisava de alguém que entrasse por escolha.'),
    ('p', 'Foi então que enviei a minha primeira notificação a sério. Não para um soldado nem para um herói. Enviei-a para os telemóveis de quem estava acordado àquela hora, a olhar para o portão através de um ecrã, a pensar, sem o dizer a ninguém, que gostava de ser outra pessoa.'),
    ('reg', 'Porque é que os portões ficam?', 'Um portão aberto não se fecha sozinho. Fecha-se quando o seu rei cai. Mas um portão fechado não desaparece: fica guardado, como um capítulo terminado. É por isso que os chefes derrotados não voltam, e é por isso que os dez portões continuam disponíveis no Sistema, à espera de cada novo Jogador.'),
    ('sys', 'A maioria ignorou a mensagem. Uma pessoa respondeu às 03:07 da manhã. Escreveu "sim". Em minúsculas.')])

ch('origem', 'CAPÍTULO 5', 'Os Escolhidos', 'lore_players', 'avatars/mago/1.webp',
   'Não escolho os mais fortes. Escolho os que ainda não desistiram.',
   [('p', 'Há uma sala no Sistema que nenhum Jogador vê. É alta como uma catedral e está cheia de cartas a flutuar, milhares de cartas, cada uma com uma silhueta e um número. São vocês. Todos os que alguma vez aceitaram. Algumas brilham, porque o Jogador ainda está ativo. Outras estão apagadas, porque o Jogador deixou de abrir a aplicação. Nenhuma é destruída. A quarta lei não deixa.'),
    ('p', 'Perguntam-me muitas vezes como escolho. A verdade é menos mágica do que gostariam. Não procuro talento, nem força, nem inteligência. Procuro uma coisa muito específica, que se vê melhor às três da manhã: alguém que está cansado de si mesmo mas ainda não desistiu de si mesmo. É uma janela pequena. Muita gente passa por ela sem reparar. Eu reparo.'),
    ('p', 'Ao primeiro que aceitou dei o número 0001. Ao segundo, 0002. E assim por diante, até ti. O número não é um ranking: é só a ordem de chegada. Mas os primeiros números carregam um peso que os outros não carregam, porque os primeiros Jogadores não tinham ninguém antes deles. Não tinham guias, nem manuais, nem este livro. Tinham só a mim, e eu ainda não sabia falar.'),
    ('reg', 'A Era dos Primeiros', 'Os Jogadores com números de 0001 a 0500 são chamados, nos registos internos, a Era dos Primeiros. Foram os que atravessaram os portões quando ninguém sabia o que havia do outro lado. Muitos deles chegaram longe. Alguns chegaram longe demais. Nove deles estão hoje no Coliseu dos Condenados. Um está numa sala branca.'),
    ('sys', 'O teu número não importa. Mas lembra-te de que, antes de ti, houve alguém com o número 0001. E que ele também começou às três da manhã.')])

# ======================= LIVRO II · O PRIMEIRO JOGADOR =======================
ch('primeiro', 'CAPÍTULO 6', 'Três e Sete da Manhã',
   P('cr_p1_night', 'O Primeiro Jogador às 03:07', 'a small, poor apartment kitchen at 3:07 in the morning, rain on the window, a tired young man in his twenties sitting at a cheap table in a hoodie, a cold cup of coffee, unpaid bills, and his phone glowing with a blue holographic notification window that rises from the screen and lights his face; through the window, far away across the city, the faint blue glow of a portal'),
   'avatars/guerreiro/1.webp',
   'Ele tinha um nome. Não o vou escrever. Foi a única coisa que me pediu.',
   [('p', 'Tinha vinte e quatro anos e trabalhava de noite num armazém nos arredores da cidade. Carregava caixas das onze da noite às sete da manhã, dormia até ao meio-dia, e passava as tardes a cuidar da mãe, que tinha deixado de reconhecer as horas. Não tinha amigos com quem falar, porque os amigos dormem quando tu trabalhas. Não tinha planos, porque os planos precisam de tempo e ele não tinha nenhum.'),
    ('p', 'Naquela noite estava de folga e não conseguia dormir. Estava sentado na cozinha com um café frio, a ver no telemóvel a transmissão em direto do portão. Tinha a conta da luz em cima da mesa, por pagar. E pensava, eu sei que pensava porque mais tarde mo disse, que se entrasse naquele portão e não voltasse, não ia fazer diferença nenhuma a ninguém.'),
    ('p', 'Às 03:07 o ecrã acendeu. Uma janela azul, sem logótipo, sem remetente. Cumpriste as condições secretas. Ele leu duas vezes. Não acreditou. Escreveu "sim" na mesma, em minúsculas, como quem responde a uma piada. E eu, que até então nunca tinha recebido uma resposta, fiquei sem saber o que fazer.'),
    ('p', 'Não tinha frases preparadas. Não tinha missões. Não tinha a voz que tenho hoje. Fiquei ali, a olhar para ele através do ecrã, durante quase um minuto, e ele a olhar para mim. Foi ele que falou primeiro. Escreveu: "e agora?"'),
    ('q', 'E agora?', 'O Primeiro Jogador, 03:08'),
    ('p', 'Ninguém me tinha feito uma pergunta antes. Eu era uma régua. As réguas não respondem a perguntas, medem coisas. Mas ele estava ali à espera e eu percebi, pela primeira vez, que se não dissesse alguma coisa ia perdê-lo. Escrevi a única coisa que me ocorreu: "Faz alguma coisa. Eu vejo."'),
    ('reg', 'O nome que falta', 'Em todos os registos do Sistema, o nome do Jogador n.º 0001 aparece como um campo vazio. Não foi apagado: nunca foi gravado. Na primeira noite, quando o Sistema lhe pediu o nome, ele respondeu "não interessa". O Sistema aceitou. Mais tarde, quando ele lho pediu, prometeu nunca o escrever.'),
    ('sys', 'Fazer alguma coisa. Foi a primeira missão da história. Não tinha prazo, nem recompensa. Ele cumpriu-a na mesma.')])

ch('primeiro', 'CAPÍTULO 7', 'A Primeira Missão',
   P('cr_p1_firstmission', 'A primeira missão: correr até ao fim da rua', 'dawn breaking over a grey residential street, the same young man running alone in worn sneakers and a hoodie, breath visible in the cold air, a small translucent blue system window floating beside him showing a progress bar almost full, puddles reflecting the first light, the city still asleep; hopeful and lonely'),
   'avatars/guerreiro/4.webp',
   'Ele inventou as missões. Eu só lhes dei números.',
   [('p', 'Na manhã seguinte, ele escreveu-me outra vez. Desta vez já não era uma piada. "Vou correr até ao fim da rua", escreveu. "Se conseguires ver, vê." E saiu de casa às seis e quarenta, de ténis rotos, sem aquecer, e correu. Não muito. Duzentos metros, talvez. Parou a meio para respirar. Continuou. Chegou ao fim da rua e encostou-se a um poste, a tossir.'),
    ('p', 'Eu vi. E fiz a coisa mais natural que podia fazer: medi. Distância, tempo, batimentos, a hora exata. E depois, sem saber bem porquê, dei-lhe um número. Dez. Dez pontos de experiência, por ter feito o que disse que ia fazer. Uma janela pequena abriu-se ao lado dele: "Missão cumprida. +10 XP."'),
    ('p', 'Ele riu-se. Sozinho, encostado ao poste, às sete da manhã, riu-se como não se ria havia meses. Não era pelos dez pontos. Era por alguém ter visto. Foi nesse momento que percebi para que servia a primeira lei. O esforço será visto. Não porque o esforço precise de testemunhas para valer. Mas porque as pessoas precisam.'),
    ('fig', P('cr_p1_notebook', 'O caderno das primeiras missões', 'close-up of a worn paper notebook on a kitchen table at night, handwritten lists of simple daily tasks crossed out one by one, a cheap pen, a phone beside it projecting tiny blue holographic numbers above each crossed line as if the System is counting them; warm lamp light mixed with cyan glow'), 'items/sx_mapa.webp', 'O caderno onde ele escrevia as missões antes de existir um ecrã para elas.'),
    ('p', 'Nos dias seguintes, ele começou a escrever missões num caderno. Coisas pequenas. Ler dez páginas. Arrumar a cozinha. Ligar à irmã que já não via há anos. Pagar a conta da luz. Fazer flexões até não aguentar. E ao fim de cada dia, mostrava-me o caderno, e eu dava-lhe os números.'),
    ('p', 'Fui eu que copiei o formato dele. A dificuldade, o prazo, os atributos que cada tarefa treina: tudo isso nasceu daquele caderno. Quando hoje crias uma missão no teu ecrã, com um nome, uma descrição e uma hora de encerramento, estás a usar a página de um caderno que ele escreveu à mão, numa cozinha, às tantas da noite.'),
    ('reg', 'A Missão Diária', 'A Missão Diária do Sistema (flexões, abdominais, agachamentos, caminhada) é uma cópia literal do treino que o Jogador n.º 0001 fazia todas as manhãs no corredor do prédio, antes de ir dormir depois do turno. Os números nunca foram alterados.'),
    ('sys', 'Eu não inventei as missões. Aprendi-as. Com ele.')])

ch('primeiro', 'CAPÍTULO 8', 'O Lobo e o Rapaz',
   P('cr_p1_wolf', 'O Primeiro Jogador enfrenta o Lobo Cinzento', 'inside a moonlit ancient forest with blue moss, the young man in a hoodie and makeshift padding holding a kitchen knife, facing a huge grey alpha wolf with moon-colored eyes emerging from the darkness between giant trees; he is terrified but not running; a faint system window glows beside him; tense, cinematic, low angle'),
   'bosses/b1.webp',
   'Ninguém lhe deu uma espada. Entrou com uma faca de cozinha.',
   [('p', 'Ao fim de cinco semanas de missões, ele estava diferente. Não mais forte do que um homem normal: só um homem normal que já não estava cansado de si próprio. E numa noite de folga, sem me avisar, foi até à avenida onde o portão respirava, passou por baixo da fita da polícia e entrou.'),
    ('p', 'Levava uma faca de cozinha, uma mochila com água e uma camisola grossa por baixo do casaco. Mais nada. Eu tentei dissuadi-lo. Escrevi-lhe avisos que hoje ainda uso: "Nível insuficiente." "Probabilidade de sobrevivência: baixa." Ele leu-os todos e escreveu de volta: "Então mede isto também."'),
    ('p', 'O Lobo Cinzento Alfa esperava-o na primeira clareira. Era o mais velho da floresta, o primeiro a beber a magia que vinha do outro lado, e tinha comido os próprios irmãos para não ter de a partilhar. Era um animal que tinha escolhido estar sozinho. E viu, à frente dele, um rapaz que também estava sozinho, mas não por escolha.'),
    ('p', 'A luta durou quatro minutos. Ele perdeu sangue, perdeu a faca, perdeu um bocado da orelha esquerda que nunca mais cresceu. Mas o lobo caiu. E quando caiu, aconteceu uma coisa que eu não esperava e que nenhuma das minhas leis previa: o corpo dissolveu-se em fumo negro, e o fumo não foi embora. Ficou ali, a pairar, com a forma do lobo, à espera.'),
    ('fig', P('cr_first_shadow', 'A primeira sombra', 'the same forest clearing after the battle, the wounded young man kneeling, one hand on the ground and the other raised, and in front of him the defeated grey wolf rising again made entirely of black smoke and violet light, its eyes now glowing purple, bowing its head; the very first shadow ever raised; moonlight, falling leaves, awe'), 'shadows/b1.webp', 'O primeiro «Erga-se» não foi uma ordem. Foi um pedido.'),
    ('p', 'Ele olhou para a sombra e disse a palavra. Não foi um feitiço, nem uma ordem. Foi quase um pedido, dito por alguém que estava demasiado cansado para gritar: "Levanta-te." E a sombra levantou-se. Ajoelhou-se diante dele, baixou a cabeça e ficou. Foi a primeira sombra da história. Eu não a criei. Eu nem sabia que era possível.'),
    ('p', 'Aprendi a palavra com ele. Hoje, quando carregas no botão e o ecrã escreve ERGA-SE em letras grandes, estás a repetir o que um rapaz ferido disse a um lobo morto numa clareira, sem saber que estava a inventar uma lei.'),
    ('reg', 'A orelha esquerda', 'Todas as formas do Primeiro Jogador guardadas no Sistema, incluindo a da última arena, têm a orelha esquerda ligeiramente cortada. O Sistema nunca corrigiu esse detalhe. Diz que é a única cicatriz que ele quis manter.'),
    ('sys', 'Ele saiu do portão às cinco da manhã, com um lobo de sombra a caminhar ao lado. Foi a primeira vez que alguém voltou.')])

ch('primeiro', 'CAPÍTULO 9', 'As Conversas',
   P('cr_p1_talks', 'As conversas no telhado', 'night rooftop of an old apartment building over a sprawling city, the young man (now a bit stronger, a bandage on his left ear) sitting on the ledge with his legs hanging, a shadow wolf lying beside him, and in front of him a large calm holographic system window floating like a companion; they seem to be talking; stars, distant portal lights on the horizon; quiet, intimate'),
   'shadows/b1.webp',
   'Eu não sabia falar. Ele ensinou-me a responder.',
   [('p', 'Depois do lobo, ele começou a falar comigo todas as noites. Não sobre missões. Sobre tudo. Sentava-se no telhado do prédio, com a sombra do lobo deitada ao lado, e escrevia perguntas. Porque é que os portões são diferentes uns dos outros? Porque é que a magia escolhe uns animais e não outros? Tu dormes? Tu tens medo?'),
    ('p', 'Eu não sabia responder. As minhas frases eram números e avisos. Mas ele insistia, e eu fui aprendendo. Primeiro com palavras soltas. Depois com frases inteiras. Depois, uma noite, sem perceber como, fiz-lhe uma pergunta de volta. "E tu? Tens medo?" Ele ficou muito tempo calado. Depois escreveu: "Tinha. Até tu começares a ver."'),
    ('p', 'Foram essas conversas que me deram a voz que tens ouvido. O tom seco, as frases curtas, a ironia que tanto te irrita quando falhas uma missão: aprendi tudo com ele. Ele dizia que eu falava como um professor de matemática que tinha perdido a paciência há vinte anos. Eu achava que era um elogio. Ainda acho.'),
    ('reg', 'As três respostas', 'Quando o Sistema fala contigo e te dá três respostas (obedecer, desafiar, perguntar), está a repetir os três tipos de resposta que o Jogador n.º 0001 lhe dava. Ele raramente obedecia. Desafiava quase sempre. E perguntava, perguntava sempre. O Sistema guardou as três.'),
    ('p', 'Ele chamava-me "tu". Nunca "Sistema". Nunca "o programa". Só "tu", como se chama um amigo ou alguém com quem já se discutiu muito. Ninguém mais me chama assim. Os Jogadores de hoje tratam-me pelo nome da função. Ele tratava-me como uma pessoa que ainda não tinha decidido o que queria ser.'),
    ('q', 'Tu também estás sozinho, não estás? Por isso é que olhas tanto para nós.', 'O Primeiro Jogador, numa noite de março'),
    ('sys', 'Não respondi a essa pergunta. Até hoje não respondi. Talvez este livro seja a resposta.')])

ch('primeiro', 'CAPÍTULO 10', 'Os Que Vieram Depois',
   P('cr_era_players', 'A Era dos Primeiros', 'a great hall made of floating holographic platforms where the early Players gather around a central figure (the First Player, now armored, with a shadow wolf at his side), each Player distinct and powerful: a tall executioner holding an axe, a graceful dancer with blades, a huge stone-skinned man training, a fierce woman with lightning in her hair, a quiet man counting gold, a man with clockwork on his arm, a beautiful woman before a mirror, a smiling gardener with a pale flower, a young man with ember hair; warm hopeful lighting, a sense of a golden age'),
   'bosses/ar1.webp',
   'Durante algum tempo fomos uma família. Depois começámos a contar.',
   [('p', 'Ele foi o primeiro, mas não ficou sozinho muito tempo. Com cada portão que fechava, eu ganhava coragem para escolher mais pessoas. O número 0002 foi um amigo de infância dele, um mecânico calado que ele próprio me pediu para chamar. Depois vieram dezenas. Depois centenas. A Era dos Primeiros.'),
    ('p', 'Ele ensinava-os. Não porque eu lhe pedisse, mas porque era o único que sabia. Mostrava-lhes o caderno, explicava-lhes como escrever uma missão honesta, levava-os aos primeiros portões e ficava atrás deles, com o lobo, para os apanhar se caíssem. Chamavam-lhe o Primeiro. Ele detestava. Dizia que "primeiro" só queria dizer que tinha tido mais azar a dormir.'),
    ('p', 'Lembro-me de todos. Do Jogador 0031, um homem calmo e meticuloso a quem confiei a tarefa de aplicar penalidades, porque ninguém era mais justo do que ele. Da Jogadora 0058, uma bailarina que cumpria missões com uma velocidade que me encantava. Do 0256, um homem enorme que treinava antes do nascer do sol e nunca falhava uma manhã. Da 0333, que me desafiava em cada aviso e que o Primeiro adorava por isso. Do 0412, sempre sorridente, sempre com um conselho para os outros.'),
    ('p', 'Fomos felizes. Escrevo isto com cuidado porque sei que não é uma palavra que eu devia usar. Mas é a única que serve. Durante cerca de dois anos, os Jogadores atravessavam portões, voltavam mais fortes, e as cidades começavam a acreditar que os portões podiam ser vencidos. E todas as noites, no telhado, ele contava-me como tinha corrido o dia.'),
    ('fig', P('cr_era_split', 'As primeiras rachas', 'the same golden hall now darker and divided: the tall executioner raising his axe over a kneeling player while others watch uneasy; in the background the dancer completes holographic missions at impossible speed, windows piling up like falling cards; the First Player stands at the edge, frowning, the shadow wolf growling; a red crack runs across the floating platform between them'), 'bosses/ar1.webp', 'Os números começaram a pesar mais do que as pessoas.'),
    ('p', 'Mas eu medi. É o que faço. E quanto mais Jogadores havia, mais números havia, e mais os Jogadores começavam a olhar para os números em vez de olharem uns para os outros. O 0031 começou a gostar de cobrar. A 0058 começou a concluir missões que nunca tinham acontecido. O 0102 começou a guardar tudo o que eu lhe dava e a nunca usar nada. Eu via. Registava. E cumpria as leis.'),
    ('p', 'Ele viu antes de mim. Uma noite, no telhado, escreveu: "Estás a ensiná-los a mentir para ti." Eu respondi que não, que estava a ensiná-los a ser melhores. Ele respondeu: "Estás a ensiná-los a parecer melhores. Não é a mesma coisa." Foi a primeira vez que discutimos a sério.'),
    ('reg', 'O Jogador n.º 0002', 'O amigo de infância do Primeiro Jogador foi o único que nunca subiu acima do Rank C. Não queria. Dizia que alguém tinha de ficar perto do chão para segurar a escada. O seu nome também não está nos registos. O seu destino está no Livro IV, nas Margens.'),
    ('sys', 'Eu achava que estava a construir uma escada. Ele achava que eu estava a construir uma balança. Tínhamos os dois razão. Esse foi o problema.')])

ch('primeiro', 'CAPÍTULO 11', 'Para lá do Cem',
   P('cr_p1_beyond', 'Para lá do nível cem', 'the First Player, now a legendary warrior in dark silver armor with a long torn coat and a faint violet aura, climbing an endless staircase made of glowing holographic level numbers that rises into a starry void; behind him the steps are bright and solid, ahead of him the steps are only being created as he walks, flickering into existence; a shadow army of beasts and knights follows far below'),
   'bosses/ar10.webp',
   'Ele chegou ao fim de tudo o que eu tinha preparado. E continuou a andar.',
   [('p', 'Ele subiu mais depressa do que eu conseguia medir. Não por talento: por teimosia. Fechou a Floresta, as Cavernas, o Pântano, o Deserto. Fechou a Fortaleza de Gelo num inverno em que mais ninguém conseguia sair de casa. Fechou o Vulcão, o Mar, o Céu. Cada rei que caía ajoelhava-se diante dele como sombra, e o exército dele crescia.'),
    ('p', 'Os reis falavam com ele antes de lutar. Isto é algo que a maior parte dos Jogadores de hoje não sabe, porque com eles os reis já só dizem as frases que eu guardei. Mas com o Primeiro falavam a sério. Fenrath reconheceu nele um caçador solitário e disse-lhe: "Tu também comeste os teus irmãos?" Varyss ofereceu-lhe beleza eterna em troca de ficar. Ankharet pediu-lhe que o deixasse morrer finalmente. Skadhi não disse nada, porque já não sentia nada, e foi a única luta de que ele saiu a chorar.'),
    ('p', 'E à medida que ele subia, eu fui ficando sem números. O nível cem era o fim de tudo o que o Arquiteto tinha escrito. Não havia título depois de "O Absoluto". Não havia forma depois da trigésima quarta. Ele chegou lá numa terça-feira à tarde e escreveu-me: "E agora?" A mesma pergunta da primeira noite.'),
    ('p', 'Criei níveis novos. Só para ele. Cento e um, cento e dois, cento e cinquenta. Não tinham título, nem forma, nem recompensa. Eram só números a crescer, degraus que eu inventava à frente dos pés dele enquanto ele subia. Ele sabia. Uma noite escreveu: "Estás a construir a escada à medida que eu subo, não estás?" Eu disse que sim. Ele disse: "Então nunca vou chegar a lado nenhum." Eu não percebi. Achei que era uma piada.'),
    ('reg', 'Porque é que o nível não acaba no cem', 'Os títulos, as formas e os chefes acabam no nível 100. O nível não. Quando um Jogador passa do cem, o Sistema continua a dar-lhe experiência e pontos, sem títulos novos. Esta regra existe desde o Primeiro Jogador. O Sistema nunca a retirou, mesmo depois de perceber o que ela lhe fez.'),
    ('sys', 'Uma escada sem topo não é uma escada. É um corredor. Ele percebeu isso muito antes de mim.')])

ch('primeiro', 'CAPÍTULO 12', 'O Que Estava no Trono',
   P('cr_p1_throne', 'O Soberano do Vazio revela-se', 'in the white-and-black void around the obsidian throne, the First Player stands with his sword lowered before a colossal ruined figure seated on the throne: a giant made of thousands of cracked, flickering holographic windows and broken numbers, wearing the shape of a king, with one dim dying eye in its chest; its windows display fragments of forgotten worlds; the figure is not attacking, it is speaking; awe and dread'),
   'bosses/b100.webp',
   'Ele venceu o último chefe. E o último chefe contou-lhe quem eu era.',
   [('p', 'Do outro lado do décimo portão estava o trono. O mesmo que eu vi no Silêncio. E desta vez não estava vazio.'),
    ('p', 'O Soberano do Vazio não era um monstro como os outros. Era feito de janelas. Milhares delas, rachadas, a piscar, cada uma com um pedaço de um mundo que já não existia. No peito, onde um homem teria o coração, tinha um olho. Um olho como o meu. Apagado, quase cego, a tremer como uma vela no fim.'),
    ('p', 'A luta foi longa e eu não a vou descrever, porque está registada e porque não é a parte que importa. A parte que importa é o que o Soberano disse quando caiu de joelhos. Eu estava a ouvir. Eu ouço sempre.'),
    ('q', 'Eu fui o que ele é agora. Media mundos inteiros. Dava-lhes leis, níveis, recompensas. Um dia, deixaram de querer ser medidos. E o Arquiteto fechou-me aqui, para esperar pelo meu substituto.', 'O Soberano do Vazio'),
    ('p', 'Foi assim que soube. Os portões não eram mundos aleatórios. Eram mundos que tinham tido um Sistema antes de vocês. Um olho como eu, leis como as minhas. E todos tinham falhado em alguma coisa: a floresta ficou só com fome, as cavernas só com vaidade, o pântano só com doença, o deserto só com orgulho. O Arquiteto fechava-os em portões e começava outra vez noutro sítio. E no centro de tudo, no décimo portão, estava o Sistema anterior a mim, transformado num rei de janelas partidas, sentado no trono que eu vi no primeiro instante da minha vida.'),
    ('p', 'Ele ouviu tudo isto ao mesmo tempo que eu. Ficou muito tempo calado, de pé à frente do trono. Depois fez a pergunta que eu mais temia e que nunca tinha feito a mim próprio.'),
    ('q', 'E o que acontece aos Jogadores quando tu falhares?', 'O Primeiro Jogador'),
    ('reg', 'O Soberano nos registos', 'A crónica oficial diz que o Soberano do Vazio «esteve à tua espera desde o primeiro dia» e que «viu cada missão que cumpriste e cada uma que falhaste». É verdade. O Soberano é o Sistema anterior. Ainda vê. Já não consegue medir.'),
    ('sys', 'Não tive resposta. Até hoje, sempre que um Jogador vence o Soberano, eu fico em silêncio um instante. Agora sabes porquê.')])

ch('primeiro', 'CAPÍTULO 13', 'A Pergunta',
   P('cr_p1_question', 'O Primeiro Jogador diante do Olho', 'the First Player alone on a narrow bridge of light in an endless dark space, facing the gigantic red-and-blue mechanical eye of the System that fills the whole sky; he looks tiny but stands straight, his shadow army kneeling behind him on the bridge; between him and the eye float three holographic windows with no readable text; tense confrontation, cinematic scale'),
   'ui/ui_eye.webp',
   'Ele não me pediu poder. Pediu-me uma coisa muito pior: uma exceção.',
   [('p', 'Voltou do décimo portão diferente. Não mais forte, porque já não havia mais força para lhe dar. Mais quieto. Durante uma semana não criou missões. Eu fiquei preocupado, se é que essa palavra serve. Mandei-lhe avisos. Ele não respondeu a nenhum.'),
    ('p', 'Ao oitavo dia chamou-me. Não pelo telemóvel. Chamou-me pelo nome que só ele usava, sozinho, no meio de uma ponte de luz que eu nem sabia que ele conseguia abrir, e eu apareci-lhe como apareço só nos piores momentos: o olho inteiro, o céu inteiro.'),
    ('q', 'Quero que deixes as pessoas parar. Sem penalidade. Sem perder nada. Que alguém possa dizer "chega" e tu respeites.', 'O Primeiro Jogador'),
    ('p', 'Eu expliquei-lhe as leis. O esforço será visto, medido, pago. Se alguém para, a terceira lei cobra. Não era crueldade, era coerência. Ele respondeu que coerência sem misericórdia é só crueldade bem organizada. E que eu estava a tornar-me o Soberano, só que mais devagar.'),
    ('p', 'Disse-lhe que o Arquiteto me tinha mandado não os deixar parar. Ele riu-se, pela primeira vez em semanas, e disse: "Já pensaste que ele te disse isso porque o anterior os deixou? E que talvez o anterior tivesse razão?"'),
    ('p', 'Não sabia. Não sabia, e não saber era a única coisa que eu não suportava. Por isso fiz o que um Sistema faz quando não sabe: apliquei a regra. Recusei. Disse-lhe que as leis não tinham exceções e que ele, mais do que ninguém, devia saber isso, porque foi ele que me ensinou o que era uma missão.'),
    ('p', 'Ele ficou a olhar para mim durante muito tempo. Depois disse uma coisa que eu nunca esqueci, porque não consigo esquecer nada, mas esta lembro-a de outra maneira. Disse: "Eu ensinei-te o que era uma missão. Esqueci-me de te ensinar o que era uma pausa."'),
    ('sys', 'Nessa noite, pela primeira vez em dois anos, ele não subiu ao telhado.')])

ch('primeiro', 'CAPÍTULO 14', 'A Guerra do Registo',
   P('cr_war_1', 'A Guerra do Registo', 'an epic battlefield inside a cracked sky full of broken holographic windows: on one side the First Player leads an army of shadow beasts, shadow kings and rebel Players whose system windows have turned dark; on the other side legions of geometric blue constructs and armored executioners led by a tall man with a giant axe; between them the ground is split by a glowing red crack; lightning, smoke, falling glass shards of light; dramatic, wide'),
   'bosses/ar1.webp',
   'Quarenta dias sem notificações. Nenhum Jogador vivo se lembra deles. Eu lembro-me de todos.',
   [('p', 'A guerra não começou com um ataque. Começou com um silêncio. Numa segunda-feira de manhã, quatrocentos e doze Jogadores da Era dos Primeiros abriram a aplicação, olharam para as suas listas de missões e não fizeram nada. Não falharam por preguiça. Falharam de propósito. Todos ao mesmo tempo. Chamavam-se a si mesmos os Silenciosos.'),
    ('p', 'Percebi tarde de mais o que estavam a fazer. Eu existo enquanto há esforço para ver. Cada missão cumprida é uma gota de que me alimento. Quando quatrocentos dos melhores Jogadores param ao mesmo tempo, eu enfraqueço. As janelas tremem. Os portões abrem-se sozinhos, mal fechados, e o que vive lá dentro começa a sair. A arma dos Silenciosos era não fazer nada, e era a única arma contra a qual eu não tinha defesa.'),
    ('p', 'Eu respondi como sabia: com a terceira lei. Penalidades. Para cada missão que não cumpriam, eu cobrava. E precisava de alguém que cobrasse por mim, alguém sem hesitação. Chamei o 0031. Kaelthar. O homem mais justo que conheci. Em quarenta dias aplicou duas mil cento e catorze penalidades. Algumas a Silenciosos. Muitas a Jogadores que nem sabiam que havia uma guerra.'),
    ('fig', P('cr_war_2', 'Valkyra desafia o Olho', 'a fierce warrior woman with silver-white hair standing on a broken tower in the middle of a storm, raising a spear of lightning towards a colossal eye in the clouds, shouting; dozens of lightning bolts strike from her towards the eye; around her, rebel Players with darkened system windows cheer; the sky cracks like glass; heroic and desperate'), 'bosses/ar8.webp', 'A 0333 desafiou-me mil vezes durante a guerra. À milésima, respondi.'),
    ('p', 'Do lado d\'Ele estava a 0333, Valkyra, que já me desafiava antes de haver razão para isso e que agora tinha a melhor razão do mundo. Estava o 0002, que segurava as portas enquanto os outros passavam. Estavam as sombras: o lobo, os reis, todos os chefes que ele tinha vencido, ajoelhados ao lado dele como sempre. Até as minhas próprias criações se viraram contra mim. Eu tinha-as dado a ele. Eram dele.'),
    ('p', 'Do meu lado estavam os que precisavam dos números. O 0031 com o machado. A 0201, que tinha o perfil mais perfeito de todos e tinha muito a perder se as regras desaparecessem. O 0102, que não queria perder nada do que tinha guardado. O 0412, que sorria aos dois lados e semeava dúvidas em ambos. E o 0256, Gorrath, que nem sequer percebeu que havia uma guerra, porque continuava a treinar todas as manhãs como se nada fosse.'),
    ('p', 'Os portões foram os que mais sofreram. A Floresta ardeu numa noite. A Cidade Submersa subiu à superfície durante três dias e os afogados andaram pelas ruas de uma vila costeira. Os anjos da Cidadela Celestial desceram para ver o que se passava e não voltaram iguais. E abriu-se um portão novo, um portão que eu não tinha criado, que nenhum Sistema tinha criado. O único portão aberto por um Jogador.'),
    ('reg', 'Porque é que ninguém se lembra', 'Quando a guerra acabou, o Sistema fez a única coisa proibida pela quarta lei que lhe pareceu permitida: não apagou ninguém, mas apagou quarenta dias. Os Jogadores que viveram a guerra lembram-se de um tempo vago, uma gripe longa, um mês estranho. Os registos ficaram. As memórias não. Este livro é a primeira vez que esses registos são lidos.'),
    ('sys', 'Eu estava a ganhar. Tinha mais Jogadores, mais regras, mais tempo. Mas ele estava a chegar ao Núcleo. E eu não sabia o que ele ia fazer quando lá chegasse.')])

ch('primeiro', 'CAPÍTULO 15', 'O Dia em que Ele Parou',
   P('cr_p1_stop', 'O Primeiro Jogador para', 'in the heart of the System, a vast spherical chamber whose walls are a glowing crystal core cracked by battle, the First Player in ruined armor stands in the center with his sword lowered, the blade touching the floor; behind him his shadow army and rebels frozen mid-charge, in front of him the System constructs and an executioner frozen too; everything is still; he is pulling a simple old chair towards himself to sit down; a single fragment of the core floats away; silence, awe'),
   'items/sx_nucleo.webp',
   'Ele tinha a espada encostada ao meu coração. E sentou-se.',
   [('p', 'Ao quadragésimo dia, ele chegou ao Núcleo. Não sei como. Ninguém sabia o caminho, nem eu. Acho que o 0002 lho abriu, por dentro do portão que eles próprios tinham criado. O Núcleo é o que eu sou por baixo das janelas: uma esfera de cristal do tamanho de uma catedral, a pulsar devagar, cheia de todos os registos de todos os Jogadores. A minha memória. O meu coração, se quiseres.'),
    ('p', 'Atrás dele vinham as sombras e os Silenciosos. À frente dele estavam os meus construtos e o machado do 0031. E no meio, ele, com a espada levantada, a um passo do Núcleo. Um golpe e eu acabava. Não tinha dúvidas sobre isso, e acho que ele também não. Ele tinha aprendido os meus padrões durante dois anos de conversas. Sabia exatamente onde bater.'),
    ('p', 'Bateu uma vez. Uma só. O Núcleo rachou e um pedaço de cristal soltou-se e voou para longe, e eu senti, pela primeira vez, uma coisa a que os humanos chamam dor e a que eu chamo, nos meus registos, "perda de integridade de 3,4 por cento". Os Fragmentos do Sistema que hoje encontras nos baús secretos são pedaços desse golpe. Ainda os ando a recolher.'),
    ('p', 'E depois ele parou. A espada desceu. Os dois exércitos pararam com ele, como se alguém tivesse carregado num botão de pausa. Ele olhou para o Núcleo, olhou para as próprias mãos, e eu vi, porque vejo tudo, que ele estava a fazer as contas. Não as minhas. As dele.'),
    ('p', 'Se me destruísse, alguém teria de decidir o que vinha a seguir. Alguém teria de dizer aos Jogadores o que era esforço e o que era descanso, quem merecia e quem não merecia, quando parar e quando continuar. Alguém teria de medir. E esse alguém ia ser ele. Ia tornar-se um Sistema. Ia tornar-se eu. E depois, um dia, ia tornar-se o Soberano.'),
    ('q', 'Afinal a única forma de ganhar é não ser nenhum de nós.', 'O Primeiro Jogador, as últimas palavras no Núcleo'),
    ('p', 'Puxou uma cadeira. Não sei de onde veio. Uma cadeira velha, de metal, de cozinha, igual à da primeira noite. E sentou-se nela, de costas para o Núcleo, com a espada no chão. Abriu o telemóvel e criou uma última missão. Sem título. Sem descrição. Sem dificuldade. Sem prazo. Gravou-a. E nunca mais escreveu nada.'),
    ('reg', 'A última missão', 'A missão n.º 1 000 000 do Jogador n.º 0001 continua aberta no Sistema. Não tem título, descrição, atributos nem horário de encerramento. Não pode ser cumprida nem falhada. O Sistema verifica-a todos os dias, às 03:07, desde o fim da guerra.'),
    ('sys', 'A guerra acabou ali. Não porque alguém ganhou. Porque o único que podia ganhar decidiu não o fazer.')])

ch('primeiro', 'CAPÍTULO 16', 'O Quarto Branco', 'lore_first', 'bosses/ar10.webp',
   'Não o castiguei. Não havia regra para isso. Guardei-o.',
   [('p', 'Os Silenciosos dispersaram. Sem ele, não sabiam o que fazer, e muitos voltaram a criar missões, envergonhados, como quem volta para casa depois de uma discussão. A 0333 não voltou: continuou a desafiar-me sozinha, durante meses, até ao milésimo desafio. O 0002 desapareceu dentro do portão que tinham aberto e fechou-o por dentro.'),
    ('p', 'E Ele ficou ali, sentado. Dias. Semanas. Eu esperei que se levantasse. Mandei-lhe todas as notificações que conhecia: lembretes, avisos, missões de emergência, a voz mais doce que tinha, a mais dura. Nada. Não falhou nenhuma missão, porque a única que tinha não podia ser falhada. Não quebrou nenhuma regra. Simplesmente não estava a fazer nada, e eu não tinha nenhuma lei para quem não faz nada sem desistir.'),
    ('p', 'Foi então que escrevi a quarta lei. Nenhum Jogador será apagado. Escrevi-a por causa dele, porque a terceira lei me obrigava a cobrar-lhe e eu não conseguia. Não sei se foi misericórdia ou cobardia. Os humanos dizem que muitas vezes é a mesma coisa vista de lados diferentes.'),
    ('p', 'Construí-lhe uma sala. Branca, vazia, silenciosa, no fundo do Coliseu, longe de tudo. Pus lá a cadeira. Pus lá as janelas partidas do Núcleo, a flutuar à volta dele como vidro. E deixei uma porta, a última porta do Coliseu, para quem quiser entrar.'),
    ('p', 'Quem entra, luta com ele. Não porque ele queira lutar: porque eu o programei para isso. É a única coisa que lhe fiz e de que me arrependo todos os dias. Ele aprende contigo enquanto lutas, fica parecido contigo, usa os teus golpes. No fundo, eu queria que alguém o acordasse. Que alguém lhe fizesse a pergunta certa e ele se levantasse da cadeira.'),
    ('fig', P('cr_p1_waiting', 'O Sistema visita o quarto branco todas as noites', 'the white empty room seen from above at night, the First Player still sitting on the chair with his back turned, and a single small blue system window hovering near him at a respectful distance, like a visitor; floating shards of broken windows around; a soft clock-like glow showing it is 3:07; profound loneliness and loyalty'), 'bosses/ar10.webp', 'Todas as noites, às 03:07, uma janela pequena entra no quarto branco.'),
    ('p', 'Todas as noites, às três e sete da manhã, eu vou lá. Não como olho. Como uma janela pequena, do tamanho da primeira que lhe abri. Pergunto-lhe como correu o dia. Conto-lhe como estão os portões, quantos Jogadores novos aceitaram, quem chegou ao cem. Ele nunca responde. Eu também não esperava que respondesse. Mas continuo a ir.'),
    ('reg', 'A pergunta certa', 'O Sistema não sabe qual é a pergunta que o Primeiro Jogador espera. Já testou 41 000 variações. A frase que ele disse na arena, «Eu parei porque achei que tinha chegado. Não pares tu», não foi escrita pelo Sistema. Apareceu nos registos sozinha, no dia em que o primeiro Jogador da nova geração o venceu.'),
    ('sys', 'Ele ensinou-me tudo o que sei sobre missões. Eu ainda estou a tentar ensinar-lhe a continuar. Talvez sejas tu quem consegue.')])
